    # Split at the solid divider.
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            panels = [grid[:r], grid[r + 1:]]
            break
    else:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                panels = [[row[:c] for row in grid],
                          [row[c + 1:] for row in grid]]
                break

    # Select the panel with the more frequent minority color, ignoring
    # the divider itself.
    def counts(panel):
        d = {}
        for row in panel:
            for x in row:
                d[x] = d.get(x, 0) + 1
        return d

    ds = [counts(p) for p in panels]
    minority_counts = [sorted(d.values())[0] for d in ds]
    panel = panels[minority_counts.index(max(minority_counts))]
    d = counts(panel)
    rare = min(d, key=d.get)
    return [[3 if x == rare else x for x in row] for row in panel]
